// Same-path real Poppler queries. Run serially without builds or recordings.
#include "ActualAuthoringRecording.h"
#include "PDFDocumentWindow.h"
int main(int argc,char **argv){const auto report=argument(1);argc=1;TWApp app(argc,argv);app.setQuitOnLastWindowClosed(false);QTimer::singleShot(50,&app,[&]{QJsonArray checks,timings;int failures=0;const auto folder=qEnvironmentVariable("TEXLINE_SELECTION_PERF_ROOT");auto check=[&](QString name,bool passed){checks.append(QJsonObject{{"name",name},{"passed",passed}});failures+=!passed;};
 if(folder.isEmpty()||!folder.contains("2026-10-21-intuitive-workflows")){check("independent shared-path fixture required",false);app.exit(1);return;}QDir().mkpath(folder);const auto file=folder+"/dense.pdf";
 {QPdfWriter writer(file);writer.setResolution(72);writer.setPageSize(QPageSize(QPageSize::A4));writer.setPageMargins(QMarginsF(0,0,0,0));QPainter painter(&writer);QFont font("Times New Roman");font.setPixelSize(8);painter.setFont(font);for(int i=0;i<64;++i)painter.drawText(QPointF(40,40+i*11),QString("L%1 Motion estimation retains independent increments and reports uncertainty for every trajectory; sample %1.").arg(i,2,10,QChar('0')));}
 auto doc=QtPDF::Backend::Document::newDocument(file);check("dense single-page PDF loads",doc&&doc->numPages()==1);if(!doc){app.exit(1);return;}auto page=doc->page(0).toStrongRef();const auto size=page->pageSizeF();const auto boxes=page->boxes();QList<QPolygonF> glyphs;for(const auto &word:boxes){for(const auto &glyph:word.subBoxes)if(glyph.boundingBox.top()<64&&!glyph.boundingBox.isEmpty())glyphs.append(QPolygonF(glyph.boundingBox));}check("three-line glyph selection exists",glyphs.size()>150);
 QString selected,full;for(int round=0;round<3;++round){for(bool paragraph:{false,true}){QElapsedTimer timer;timer.start();const auto text=page->selectedText(paragraph?glyphs:QList<QPolygonF>{QPolygonF(QRectF(QPointF(),size))},nullptr,nullptr,true);const auto elapsed=timer.nsecsElapsed()/1e6;timings.append(QJsonObject{{"kind",paragraph?"paragraphGlyphs":"wholePage"},{"round",round},{"ms",elapsed},{"characters",text.size()}});if(paragraph)selected=text;else full=text;}}
 check("paragraph excludes unrelated later lines",selected.contains("L00")&&selected.contains("L02")&&!selected.contains("L03")&&!selected.contains("L10"));check("whole page retains final line",full.contains("L63"));put(folder+"/selected-"+qEnvironmentVariable("TEXLINE_SELECTION_PERF_LABEL","unknown")+".txt",selected.toUtf8());put(report,QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures},{"timings",timings},{"glyphs",glyphs.size()},{"words",boxes.size()},{"physicalInput",false}}).toJson());app.exit(failures?1:0);
});return app.exec();}
